function questions(values: readonly (readonly [string, string, readonly [string, string, string], string])[], offset: number) {
  return values.map(([prompt, correct, distractors, explanation], i) => q(prompt, correct, [...distractors], explanation, offset + i)) as [LabQuestion, LabQuestion, LabQuestion];
}
export const c1Modules: LabModule[] = rows.map((row, i) => ({
  id: structureLessons[i].id, title: row.title, lesson: structureLessons[i],
  reading: { title: row.title, passage: row.passage, questions: questions(row.reading, i) },
  listening: { lines: row.dialogue.map((text, index) => ({ speaker: index % 2 ? "Adviser" : "Student", text })), questions: questions(row.listening, i + 1), audioAssetPath: `/audio/c1-lab/${structureLessons[i].id}-us.m4a` },
  speaking: [...row.speaking], writing: [...row.writing],
}));

export function getLabModule(id: string) { return c1Modules.find((module) => module.id === id); }
export const productiveTasks = c1Modules.flatMap((module) => [
  ...module.speaking.map((prompt, i) => ({ id: `${module.id}-speaking-${i + 1}`, moduleId: module.id, title: module.lesson.title, skill: "speaking" as const, taskNumber: (i < 2 ? 1 : 2) as 1 | 2, prompt, frame: module.lesson.speakingFrame })),
  ...module.writing.map((prompt, i) => ({ id: `${module.id}-writing-${i + 1}`, moduleId: module.id, title: module.lesson.title, skill: "writing" as const, taskNumber: (i + 1) as 1 | 2, prompt, frame: module.lesson.speakingFrame })),
]);
export type ProductiveTask = typeof productiveTasks[number];
